    public static void main(String[] args) throws Exception {
        FastScanner fs=new FastScanner(); int T=fs.nextInt();
        while(T-->0){
            long t1=fs.nextLong(), r1=fs.nextLong(), t2=fs.nextLong(), r2=fs.nextLong();
            BigInteger left=BigInteger.valueOf(t1).pow(2).multiply(BigInteger.valueOf(r2).pow(3));
